def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separates groups of nested parentheses into separate strings.

    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, each representing a separate group of balanced parentheses.
    """
    result = []
    current_group = []
    balance = 0

    for char in paren_string:
        if char == ' ':
            continue
        current_group.append(char)
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        if balance == 0 and current_group:
            result.append(''.join(current_group))
            current_group = []

    if balance != 0:
        raise ValueError("Input string is not balanced")

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x-1][y-1] = val

    # DP table to store the maximum values collected by two paths
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * N + 1)]
    dp[0][0][0] = 0

    # Fill the DP table
    for t in range(1, N * N + 1):
        for i in range(N):
            for j in range(N):
                for k in range(N):
                    l = t - (i + j + k - k)  # l is determined by t, i, j, k
                    if 0 <= l < N:
                        val1 = grid[i][j]
                        val2 = grid[k][l]
                        current_value = val1 if i != k or j != l else val1

                        # Update the DP table from all possible previous steps
                        if i > 0:
                            dp[t][i][j] = max(dp[t][i][j], dp[t-1][i-1][j] + current_value)
                        if j > 0:
                            dp[t][i][j] = max(dp[t][i][j], dp[t-1][i][j-1] + current_value)
                        if k > 0:
                            dp[t][i][j] = max(dp[t][i][j], dp[t-1][k-1][l] + current_value)
                        if l > 0:
                            dp[t][i][j] = max(dp[t][i][j], dp[t-1][k][l-1] + current_value)

    # The result is the maximum value collected by two paths reaching the bottom-right corner
    return dp[N * 2 - 2][N-1][N-1] if dp[N * 2 - 2][N-1][N-1] != -float('inf') else 0

def find_number_combinations():
    def is_unique_digits(num1, num2, num3):
        digits = str(num1) + str(num2) + str(num3)
        return len(set(digits)) == len(digits) and '0' not in digits

    result = []
    for num1 in range(100, 1000):
        num2 = 2 * num1
        num3 = 3 * num1
        if num2 < 1000 and num3 < 1000 and is_unique_digits(num1, num2, num3):
            result.append((num1, num2, num3))

