def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        return 0
    if m == 0:
        return 1 if n == 1 else 0

    # dp[i][j] will be the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0]

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if statement in days_of_week:
                continue  # Ignore statements about the day of the week

            is_liar = participant in liar_count
            if statement == f"I am guilty.":
                if (participant == scenario) != is_liar:
                    return False
            elif statement == f"I am not guilty.":
                if (participant != scenario) != is_liar:
                    return False
            elif f"{scenario} is guilty." in statement:
                if (scenario == scenario) != is_liar:
                    return False
            elif f"{scenario} is not guilty." in statement:
                if (scenario != scenario) != is_liar:
                    return False
            elif f"{participant} is guilty." in statement:
                target = statement.split()[0]
                if (target == scenario) != is_liar:
                    return False
            elif f"{participant} is not guilty." in statement:
                target = statement.split()[0]
                if (target != scenario) != is_liar:
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("System must be either 11 or 21 points.")

    player_score = 0
    opponent_score = 0
    game_scores = []

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("Points string must only contain 'W' or 'L'.")

        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[i] is True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    # Iterate over each volume
    for volume in volumes:
        # Update the DP array from back to front
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be occupied
    max_occupied_volume = 0
    for i in range(V + 1):
        if dp[i]:
            max_occupied_volume = i

    # The minimum remaining space is the difference between the box's capacity and the max occupied volume
    return V - max_occupied_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]
